mapper.select:
SELECT ROW_NUMBER() OVER (ORDER BY faq_no ASC) as rnum ,faq_type ,faq_no ,faq_question ,faq_answer ,inquire_cnt ,reg_dt FROM seinfo_faq
faq_type = #{faqType}
LIMIT #{pageSize} OFFSET #{startRow}

mapper.insert:

			SELECT IFNULL(
			       (SELECT CAST(faq_no AS UNSIGNED) + 1
			          FROM seinfo_faq
			          WHERE faq_type =#{faqType}
			          ORDER BY faq_no DESC
			          LIMIT 1
			        ), 1)


		INSERT INTO
			seinfo_faq
        	( 	  faq_type
				, faq_no
				, faq_question
				, faq_answer
				, inquire_cnt
				, reg_dt
				, reg_user_id
				, mod_dt
				, mod_user_id
        	)VALUES
        	(	  #{faq_type}
				, #{faq_no}
				, #{faq_question}
				, #{faq_answer}
				, 0
				, now()
				, #{userEmail}
				, now()
				, #{userEmail}
			)

mapper.update:
UPDATE
	seinfo_faq
   SET inquire_cnt = inquire_cnt+1
 WHERE faq_type = #{faqType}
   AND faq_no = #{faqNo}

mapper.select:
SELECT rnum
FROM (
    SELECT
        faq_no,
        ROW_NUMBER() OVER (ORDER BY faq_no ASC) AS rnum
    FROM seinfo_faq


			faq_type = #{faqType}


	 )sub
WHERE faq_no = #{faqNo}
